# Map words to their lengths
words = ["cat", "dog", "elephant", "bird"]
word_lengths = {word: len(word) for word in words}
print(word_lengths)

# Create from two lists
keys = ["a", "b", "c"]
values = [1, 2, 3]
my_dict = {k: v for k, v in zip(keys, values)}
print(my_dict)

