def greet_person(name):
    """Print a greeting."""
    print(f"Hello, {name}!")

greet_person("Alice")

def classify_temperature(temp):
    """Classify temperature as cold, moderate, or hot."""
    if temp &lt; 70:
        return "cold"
    elif temp &lt; 85:
        return "moderate"
    else:
        return "hot"

print(classify_temperature(75))

