def get_region(row):
    if row['northcen'] == 1:
        return 'North Central'
    elif row['south'] == 1:
        return 'South'
    elif row['west'] == 1:
        return 'West'
    else:
        return 'Northeast'

wages['Region'] = wages.apply(get_region, axis=1)

