def get_industry(row):
    if row['construc'] == 1:
        return 'Construction'
    elif row['ndurman'] == 1:
        return 'Non-durable Manufacturing'
    elif row['trcommpu'] == 1:
        return 'Transportation/Communications'
    elif row['trade'] == 1:
        return 'Trade'
    elif row['services'] == 1:
        return 'Services'
    elif row['profserv'] == 1:
        return 'Professional Services'
    else:
        return 'Other'

wages['Industry'] = wages.apply(get_industry, axis=1)

